import * as fs from 'node:fs';
import * as path from 'node:path/posix';
import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { DateTime } from 'luxon';
import { AppLogger } from '@/common/logger/app-logger';
import { Mapping } from '@/common/mapping/interface/mapping.model';
import { PlantsResponseDto } from '@/common/subscribe/dtos/plant.response.dto';

@Injectable()
export class MappingUtilsService {
  public constructor(private readonly customLogger: AppLogger) {}

  /**
   * Loads mappings from a file in the filesystem.
   * @param filePath - The relative path to the file containing mappings.
   * @returns An array of Mapping objects loaded from the file.
   * @throws {Error} Throws an error if the file cannot be read or parsed.
   */
  public loadMappings(filePath: string): Array<Mapping> {
    const context: JobsLogContext = {
      method: 'loadMappings',
      service: 'MappingUtilsService',
    };
    // Prefer process.cwd to satisfy lint rule against __dirname in certain build setups
    const absolutePath = path.resolve(__dirname, filePath);

    try {
      const rawData = fs.readFileSync(absolutePath, 'utf8');
      interface RawKey {
        keySource: string;
        keyDestination: string;
        type?: string;
      }
      interface RawColumn {
        columnSource: string;
        columnDestination: string;
        type?: string;
        allowEmpty?: boolean;
      }
      interface RawEntry {
        source?: string;
        destination?: string;
        keys?: Array<RawKey>;
        destinations?: Array<{ name: string; columns: Array<RawColumn> }>;
        columnMappings?: Array<RawColumn>;
      }
      const parsed = JSON.parse(rawData) as Array<RawEntry>;
      // Backward compatibility: flatten objects with destinations[] into Mapping objects
      const flattened: Array<Mapping> = [];
      for (const entry of parsed) {
        if (entry?.source && Array.isArray(entry?.destinations)) {
          for (const destination of entry.destinations ?? []) {
            flattened.push({
              columnMappings: destination?.columns ?? [],
              destination: destination?.name,
              keys: entry.keys ?? [],
              source: entry.source,
            });
          }
        } else if (entry?.source && entry?.destination) {
          flattened.push(entry as unknown as Mapping);
        }
      }
      return flattened;
    } catch (error) {
      this.customLogger.error(
        `Error loading mappings from file ${filePath}: ${error}`,
        context,
      );
      throw new Error(`Error loading mappings from file ${filePath}: ${error}`);
    }
  }

  /**
   * Determines if a given database is marked as "WIP" (Work In Progress).
   * @param databaseName - The name of the database.
   * @returns True if the database is "WIP", false otherwise.
   */
  public isWIP(databaseName: string | undefined): boolean {
    const context: JobsLogContext = {
      method: 'isWIP',
      service: 'MappingUtilsService',
    };
    if (databaseName) {
      return databaseName === 'WIP';
    }
    this.customLogger.error(`DB Name is missed : default isWip false`, context);
    return false;
  }

  /**
   * Checks if a field in the schema is of type timestamp.
   * @param type - The type of the field to check.
   * @returns True if the field is a timestamp, false if it is not, and undefined if the field is not found.
   */
  public findFieldWithTimestamp(type: string | undefined): boolean {
    const context: JobsLogContext = {
      method: 'findFieldWithTimestamp',
      service: 'MappingUtilsService',
    };
    try {
      if (type) {
        if (type === 'timestamp') {
          return true;
        }
        return false;
      }
      return false;
    } catch (error) {
      this.customLogger.error(
        `error in finding the type ${error.message}`,
        context,
      );
      return false;
    }
  }

  /**
   * Converts a timestamp to a Date object, considering the timezone offset if applicable.
   * @param timestamp - The timestamp to convert.
   * @param isWip - The source of the database is Wip or not.
   * @param timeZone - The timezone to consider for the conversion.
   * @returns The converted Date object, or undefined if the timestamp is invalid.
   */
  public convertTimestampToDate(
    timestamp: number,
    isWip: boolean,
    timeZone: string | undefined,
  ): Date | undefined {
    const context: JobsLogContext = {
      method: 'convertTimestampToDate',
      service: 'MappingUtilsService',
    };
    let utcDate: Date;
    if (timestamp === undefined) {
      this.customLogger.debug(`timestamp is undefined`, context);
      return undefined;
    }
    if (timestamp === 0) {
      this.customLogger.debug(`timestamp is null`, context);
      return undefined;
    }
    utcDate = new Date(timestamp);
    if (isWip) {
      utcDate = new Date(
        utcDate.getTime() + utcDate.getTimezoneOffset() * 60_000,
      );
      return utcDate;
    }
    if (timeZone) {
      // Const utcDateString = moment(timestamp).tz(timeZone).toISOString();
      const sourceDateTime = DateTime.fromMillis(timestamp, { zone: timeZone });
      const utcDateTime = sourceDateTime
        .toUTC()
        .minus({ milliseconds: sourceDateTime.offset * 60_000 });
      const utcDateString = utcDateTime.toISO();
      if (!utcDateString) {
        return undefined;
      }
      utcDate = new Date(utcDateString);
      utcDate = new Date(
        utcDate.getTime() + utcDate.getTimezoneOffset() * 60_000,
      );
    }
    return utcDate;
  }

  /**
   * Retrieves the timezone for a specific plant by its ID.
   * @param plantId - The ID of the plant.
   * @param plantList Array of list Plant
   * @returns The timezone associated with the plant, or undefined if it cannot be retrieved.
   */
  public getTimeZoneForPlant(
    plantId: number,
    plantList: Array<PlantsResponseDto>,
  ): string | undefined {
    const context: JobsLogContext = {
      method: 'getTimeZoneForPlant',
      service: 'MappingUtilsService',
    };
    try {
      const plantTimeZone = this.findPlantTimeZone(plantList, Number(plantId));

      return plantTimeZone;
    } catch (error) {
      this.customLogger.error(
        `Error retrieving time zone for plant ${plantId}: ${error.message}`,
        context,
        error.stack,
      );
      return undefined;
    }
  }

  /**
   * Finds the timezone for a specific plant by its ID from a list of plants.
   * @param plants - An array of plant response DTOs.
   * @param plantId - The ID of the plant to find.
   * @returns The timezone of the plant, or undefined if the plant is not found.
   */
  private findPlantTimeZone(
    plants: Array<PlantsResponseDto>,
    plantId: number,
  ): string | undefined {
    // Using this.customLogger to satisfy lint rule expecting this usage
    if (!plants || plants.length === 0) {
      this.customLogger.verbose('plants array empty when searching timezone', {
        method: 'findPlantTimeZone',
        service: 'MappingUtilsService',
      });
      return undefined;
    }
    return plants.find((plantFind) => plantFind.plantId === plantId)?.timeZone;
  }

  /**
   * Converts a hexadecimal string to a cleaned hexadecimal string (removing any non-hexadecimal characters).
   * @param hex - The hexadecimal string to clean.
   * @returns The cleaned hexadecimal string, or undefined if the input is invalid.
   */
  public hexStringToNumber(hex: string): string | undefined {
    const context: JobsLogContext = {
      method: 'hexStringToNumber',
      service: 'MappingUtilsService',
    };
    // Removing any colon (:) separators
    if (hex === undefined) {
      this.customLogger.error(`hex is undefined`, context);
      return undefined;
    }
    const cleanedHex = hex.replaceAll(/[^\da-f]/gi, '').toLowerCase();
    return cleanedHex;
  }

  /**
   * Converts a plant local hour to UTC based on its timezone.
   * @param localHour Hour in plant local time (0-23)
   * @param timezone Plant timezone (UTC-4, GMT+2, Europe/Paris, etc.)
   * @param referenceDate Optional reference date used for DST evaluation
   * @returns UTC hour (0-23) or undefined if invalid
   */
  public convertPlantLocalHourToUtc(
    localHour: number | undefined,
    timezone: string | undefined,
    referenceDate: Date = new Date(),
  ): number | undefined {
    const context: JobsLogContext = {
      method: 'convertPlantLocalHourToUtc',
      service: 'MappingUtilsService',
    };
    if (localHour === undefined || localHour === null) {
      this.customLogger.verbose('localHour is undefined/null', context);
      return undefined;
    }
    if (localHour < 0 || localHour > 23) {
      this.customLogger.error(`localHour out of range: ${localHour}`, context);
      return undefined;
    }
    if (!timezone) {
      return localHour; // Assume already UTC
    }
    try {
      const simpleTzRegex = /^(?:utc|gmt)([+-]\d{1,2})$/i;
      const simpleTzMatch = simpleTzRegex.exec(timezone);
      if (simpleTzMatch) {
        const offsetNumber = Number(simpleTzMatch[1]); // E.g. -4
        // Local = UTC + offset => UTC = Local - offset
        const utc = (localHour - offsetNumber + 24) % 24;
        return utc;
      }
      // IANA timezone path
      const dtLocal = DateTime.fromObject(
        {
          day: referenceDate.getUTCDate(),
          hour: localHour,
          month: referenceDate.getUTCMonth() + 1,
          year: referenceDate.getUTCFullYear(),
        },
        { zone: timezone },
      );
      if (!dtLocal.isValid) {
        this.customLogger.error(
          `Invalid local DateTime for timezone ${timezone}: ${dtLocal.invalidReason}`,
          context,
        );
        return undefined;
      }
      return dtLocal.toUTC().hour;
    } catch (error) {
      this.customLogger.error(
        `Error converting local hour to UTC with timezone ${timezone}: ${error.message}`,
        context,
        error.stack,
      );
      return undefined;
    }
  }
}

import { Module } from '@nestjs/common';
import { MutexManagerService } from '@/common/mutex-manager/mutex-manager.service';

@Module({
  exports: [MutexManagerService],
  providers: [MutexManagerService],
})
export class MutexManagerModule {}

import { Mutex } from 'async-mutex';

export class MutexManagerService {
  private readonly mutexes: Map<string, { mutex: Mutex; lastUsed: number }>;

  private readonly cleanupInterval: number; // In milliseconds

  private readonly cleanupThreshold: number; // Inactivity time threshold

  public constructor(cleanupInterval = 60_000, cleanupThreshold = 300_000) {
    // 60 seconds, 5 minutes threshold
    this.mutexes = new Map();
    this.cleanupInterval = cleanupInterval;
    this.cleanupThreshold = cleanupThreshold;
    this.startCleanupThread();
  }

  // Get or create a mutex for a given cacheKey
  public getMutex(cacheKey: string): Mutex {
    let mutexEntry = this.mutexes.get(cacheKey);
    if (mutexEntry) {
      mutexEntry.lastUsed = Date.now(); // Update the last used timestamp
    } else {
      mutexEntry = { lastUsed: Date.now(), mutex: new Mutex() };
      this.mutexes.set(cacheKey, mutexEntry);
    }
    return mutexEntry.mutex;
  }

  // Start a cleanup thread to remove inactive mutexes
  private startCleanupThread(): void {
    setInterval(() => {
      const now = Date.now();
      for (const [key, entry] of this.mutexes.entries()) {
        if (now - entry.lastUsed > this.cleanupThreshold) {
          this.mutexes.delete(key); // Remove inactive mutex
        }
      }
    }, this.cleanupInterval);
  }
}

/**
 * Sleep function
 * @param time number of ms to wait
 * @returns void
 */
export async function asyncSleep(time: number): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, time);
  });
}

