import { HttpMethod } from '@dapr/dapr';
import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import { AppLogger } from '../logger/app-logger';
import { PlantsResponseDto } from '@/common/subscribe/dtos/plant.response.dto';
import { SubscribeResponseDto } from '@/common/subscribe/dtos/subscribe.response.dto';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';
import { RedisConfigService } from '@/config/redis/redis-store/redis-store.service';

@Injectable()
export class SubscribeMessageService {
  private readonly daprClient: DaprClient;

  private readonly context: JobsLogContext = {
    method: '',
    service: SubscribeMessageService.name,
  };

  public constructor(
    private readonly redisConfigService: RedisConfigService,
    private readonly daprConfigService: DaprConfigService,
    private readonly customLogger: AppLogger,
  ) {
    this.daprClient = new DaprClient();
  }

  public async handleMessage(message: SubscribeResponseDto): Promise<void> {
    try {
      Object.assign(this.context, {
        method: 'handleMessage',
        object: message,
      });
      const plants = await this.fetchPlant();
      await this.savePlantsInRedis(plants);
    } catch (error) {
      this.customLogger.error(
        `Error processing message: ${error}`,
        this.context,
      );
    }
  }

  public async savePlantsInRedis(
    plants: Array<PlantsResponseDto>,
  ): Promise<void> {
    Object.assign(this.context, {
      method: 'savePlantsInRedis',
      object: plants,
    });
    try {
      const { redisPlantKey, redisStoreAmr } = this.redisConfigService;
      this.customLogger.debug(
        `Start saving list of plant : ${JSON.stringify(plants)} in Redis store with key: ${redisPlantKey}`,
        this.context,
      );
      const dataToCache = {
        key: redisPlantKey,
        value: [plants],
      };

      await this.daprClient.state.save(redisStoreAmr, [dataToCache]);

      this.customLogger.log(
        `List of plant saved: ${JSON.stringify(plants)} in Redis store with key: ${redisPlantKey}`,
        this.context,
      );
    } catch (error) {
      this.customLogger.error(
        `Error saving list of plant in Redis: ${error}`,
        this.context,
        error.stack,
      );
    }
  }

  public async fetchPlant(): Promise<Array<PlantsResponseDto>> {
    Object.assign(this.context, {
      method: 'fetchPlant',
    });
    const options =
      process.env.TOKEN === ''
        ? {}
        : { headers: { authorization: `Bearer ${process.env.TOKEN}` } };
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethod = `plant/Plants`;
    const response = await this.daprClient.invoker
      .invoke(serviceAppId, serviceMethod, HttpMethod.GET, undefined, options)
      .catch((error) => this.customLogger.error(error, this.context));
    if (response) {
      this.customLogger.log(
        `succeed in fetching plants :${JSON.stringify(response)}`,
        this.context,
      );
      return response as Array<PlantsResponseDto>;
    }
    throw new Error('Invalid response from fetchPlant');
  }
}

import { Injectable, OnModuleInit, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

@Injectable()
export class AppConfigInitialConfigService implements OnModuleInit {
  private readonly logger = new Logger(AppConfigInitialConfigService.name);

  public constructor(private readonly configService: ConfigService) {}

  public onModuleInit(): void {
    this.checkConfiguration();
  }

  public get appConfigCachingTtl(): number {
    return this.configService.get<number>('appConfigCachingTtl') ?? 20_000;
  }

  public get appConfigEndpoint(): string {
    return this.configService.get<string>('appConfigEndpoint') ?? '';
  }

  private checkConfiguration(): void {
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [{ key: 'appConfigEndpoint', value: this.appConfigEndpoint }];

    /*
     * Check mandatory fields
     */
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.logger.error(`Missing configuration value for ${config.key}`);
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.logger.log(
      'All required "App Config Initial Configuration" configurations are properly set',
    );
  }
}

