@Injectable()
export class IngestionPolicyConfigService implements OnModuleInit {
  public constructor(
    private readonly configService: ConfigService,
    private readonly customLogger: AppLogger,
    private readonly appConfigService: AppConfigService,
  ) {}

  // Common config getters
  public async appConfigAllowedPlantResources(): Promise<string | undefined> {
    let value = this.configService.get<string>('allowedPlantsAndResources');
    const context: JobsLogContext = {
      method: 'checkConfiguration',
      service: 'AppConfigVariablesService',
    };
    if (value) {
      this.customLogger.verbose(
        `'appConfigAllowedPlantResources' was read from environment variable`,
        context,
      );
    } else {
      const configValue = await this.appConfigService.getConfigurationValue(
        'RSRCE_DI_ALLOWED_PLANTS_RESOURCES_V2',
      );
      value = configValue;
    }

    return value;
  }

  public onModuleInit(): void {
    this.checkConfiguration();
  }

  private async checkConfiguration(): Promise<void> {
    const context: JobsLogContext = {
      method: 'checkConfiguration',
      service: 'AppConfigVariablesService',
    };

    // Required configurations for managed identity authentication
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      {
        key: 'appConfigAllowedPlantResources',
        value: await this.appConfigAllowedPlantResources(),
      },
    ];

    // Check mandatory fields
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          context,
        );
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.customLogger.debug(
      'All required configurations for app config variables are properly set',
      context,
    );
  }
}

